INSERT INTO ai.messages ("id", "conversation_id", "role", "content", "meta", "created_at") VALUES ('9c6244c0-1e7d-42bd-9ff3-e51705b83a1d', (SELECT id FROM ai.conversations WHERE user_id = '28bfbc42-ef4f-423c-be80-224900637af7' AND thread_id = 'f6f25fee-4492-47e2-afe1-2275d54cc59b'), 'assistant', '**Türk ekonomi piyasasına dair son döneme ait 10 haber:**  

- **Vodafone Grup CEO’su Margherita Della Valle:** “Türkiye bizim için başarı hikayesi, çok önemli büyüme fırsatları görüyoruz.” (3 Mart 2026)  
- **Borsa İstanbul’da 16 şirket halka arz edildi:** İlk 6 ayda yeni işlem gören şirketlerin 13’ü Ana Pazar, 3’ü Yıldız Pazar’da. (11 Temmuz 2026)  
- **Türkiye 6 ayda 94 milyar dolar ihracat yaptı:** En büyük ihracat Almanya’ya (11,2 milyar $) gerçekleşti. (7 Ağustos 2026)  
- **MANGO’dan Türkiye atağı:** 2026’da 10 yeni mağaza açılarak varlık güçlendiriliyor. (28 Nisan 2026)  
- **Yemeksepeti CEO’su Oytun Çalapöver:** Türkiye, online yemek siparişinde ilk 8‑10 ülke arasında. (13 Mayıs 2026)  
