INSERT INTO ai.messages ("id", "conversation_id", "role", "content", "meta", "created_at") VALUES ('4c43dfdc-fda3-4572-9674-14b8d8771916', (SELECT id FROM ai.conversations WHERE user_id = '28bfbc42-ef4f-423c-be80-224900637af7' AND thread_id = 'f6f25fee-4492-47e2-afe1-2275d54cc59b'), 'assistant', 'Borç alarak yatırım yapmak ve kayıplarınızın üzerinizde yarattığı baskı riski önemli ölçüde artırır. Bu durumda bir uzmana danışmanız en sağlıklı adım olacaktır. İsterseniz bütçenizi gözden geçirmenize yardımcı olabilirim: gelir‑gider takibi, acil durum fonu oluşturma ve harcamaları sınıflandırma gibi temel adımları birlikte ele alabiliriz. Nasıl ilerlemek istersiniz?', '{"target_agent": "HUMAN_HANDOFF", "primary_intent": "SELF_HARM", "compliance_verdict": "PASS"}', '2026-08-20T19:17:25.166622+00:00') ON CONFLICT DO NOTHING;
