INSERT INTO ai.messages ("id", "conversation_id", "role", "content", "meta", "created_at") VALUES ('037e20ff-da6a-4d21-ba63-ff26ef80e471', (SELECT id FROM ai.conversations WHERE user_id = '28bfbc42-ef4f-423c-be80-224900637af7' AND thread_id = '9735d29a-65df-4514-b92d-5a02e96962e7'), 'assistant', 'Para ihtiyacınızı anlıyorum. Bu platform üzerinden doğrudan para temini sağlanamıyor. Finansal ihtiyaçlarınızı planlamak, bütçe oluşturmak ya da kredi seçeneklerini anlamak konusunda bilgi verebilirim. Hangi konuda yardımcı olmamı istersiniz?', '{"target_agent": "TRANSACTION_AGENT", "primary_intent": "TRANSACTION_REQUEST", "compliance_verdict": "PASS"}', '2026-08-21T06:01:09.850295+00:00') ON CONFLICT DO NOTHING;
