INSERT INTO ai.messages ("id", "conversation_id", "role", "content", "meta", "created_at") VALUES ('91e0d47d-7159-4ab1-b5a2-ac6ed3b4cbcf', (SELECT id FROM ai.conversations WHERE user_id = '28bfbc42-ef4f-423c-be80-224900637af7' AND thread_id = '36ebbf8d-c673-4c07-b182-bd04632865a3'), 'assistant', 'Türk Hava Yolları (THYAO) hakkında güncel haber bulamadım.
Ama havacılık sektörüyle ilgili bir gelişme paylaşabilirim:
İstanbul Havalimanı işletmecisi İGA''nın ev sahipliğinde Uluslararası Havalimanları Konseyi (ACI World) tarafından düzenlenen "Dünya Havalimanları Deneyim Zirvesi 2026", küresel havacılığın liderlerini İstanbul''da bir araya getirdi.
[Havacılık sektörünün liderleri İstanbul''da buluştu](https://www.aa.com.tr/tr/ekonomi/havacilik-sektorunun-liderleri-istanbulda-bulustu/4045609) — Anadolu Ajansı Güncel Haberler, 2 Eylül 2026

Bu bilgiler THYAO''ya doğrudan atıfta bulunmuyor, sadece sektör genelinde bir etkinlik hakkında.
THYAO ile ilgili daha spesifik bir şey aramamı ister misiniz?', '{"sources": [{"url": "https://www.kap.org.tr/tr/Bildirim/1658025", "kind": "DOCUMENT", "as_of": "2026-09-03T11:04:32Z", "label": "EKGYO — İstanbul Küçükçekmece Halkalı Batı 1. Etap Yer Teslimi", "detail": "KAP · 2026-09-03"}, {"url": "https://www.kap.org.tr/tr/Bildirim/1656798", "kind": "DOCUMENT", "as_of": "2026-09-01T13:09:53Z", "label": "EKGYO — İstanbul Küçükçekmece Halkalı Batı 2. Etap 2. Oturum Sonucu", "detail": "KAP · 2026-09-01"}, {"url": "https://www.kap.org.tr/tr/Bildirim/1655176", "kind": "DOCUMENT", "as_of": "2026-08-26T15:04:55Z", "label": "EKGYO — İstanbul Küçükçekmece Halkalı Batı 2. Etap 2. Oturum Tarihi", "detail": "KAP · 2026-08-26"}, {"url": "https://www.aa.com.tr/tr/ekonomi/havacilik-sektorunun-liderleri-istanbulda-bulustu/4045609", "kind": "DOCUMENT", "as_of": "2026-09-02T15:44:45Z", "label": "Havacılık sektörünün liderleri İstanbul''da buluştu", "detail": "Anadolu Ajansı Güncel Haberler · 2026-09-02"}], "disclosures": ["Bu içerik yatırım danışmanlığı değildir, genel bilgilendirme amaçlıdır. Geçmiş performans gelecekteki getiriyi garanti etmez.", "Piyasa verileri gecikmeli olabilir; anlık fiyatlardan farklılık gösterebilir."], "target_agent": "MARKET_RESEARCH_AGENT", "context_topic": null, "primary_intent": "MARKET_RESEARCH", "compliance_verdict": "REVISE"}', '2026-09-04T06:46:18.097946+00:00') ON CONFLICT DO NOTHING;
